Expected SQL Query:
SELECT UNITID
FROM ipedsdata.gr2022_l2_rv
WHERE NRLIN45 = 0 OR NRLIN10 = 0;

SELECT COUNT(DISTINCT UNITID)
FROM ipedsdata.gr2022_pell_ssl_rv
WHERE PGREVCT IS NOT NULL;

SELECT 
  SUM(pgcmtot) AS total_pell_completions
FROM ipedsdata.gr2022_pell_ssl_rv;

SELECT "UNITID", "F1B06"
 FROM ipedsdata.ipeds_finance_data1 
WHERE "F1B06" > 0;

SELECT 
    var.varname, 
    var."varTitle",
    COUNT(DISTINCT data."UNITID") AS institutions_reporting
FROM ipedsdata.ipeds_finance_f2_data data
JOIN ipedsdata.ipeds_finance_f2 var ON var.varname = 'F2A01'
GROUP BY var.varname, var."varTitle"
HAVING COUNT(DISTINCT data."UNITID") > 100;

SELECT 
    AVG(data."F2A01") AS avg_long_term_investments
FROM ipedsdata.ipeds_finance_f2_data data;

SELECT DISTINCT "codevalue", "frequency"
 FROM ipedsdata.ipeds_finance_f2
 WHERE "varname" = 'F2A01';

SELECT 
    STDDEV_POP(data."F2A05") AS stddev_restricted_net_assets
FROM ipedsdata.ipeds_finance_f2_data data;

SELECT 
    ROUND(
        COUNT(*) FILTER (WHERE data."F2A19" = 0) * 100.0 / NULLIF(COUNT(*), 0), 2
    ) AS percent_zero_endowment_assets
FROM ipedsdata.ipeds_finance_f2_data data;

SELECT COUNT(*) FROM ipedsdata.ipeds_finance_f2
 WHERE "varname" = 'F2A01' 
AND "codevalue" = 'R';

SELECT DISTINCT "varTitle"
 FROM ipedsdata.ipeds_finance_f2 
WHERE "varname" = 'F2I03';
